<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_customers');
$err='';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'add';try{
 if($action==='add'){$code=trim($_POST['customer_code']??'');$name=trim($_POST['name']??'');$mobile=trim($_POST['mobile']??'');$gstin=trim($_POST['gstin']??'');$address=trim($_POST['address']??'');$state=trim($_POST['state_code']??'');if($state!==''&&!preg_match('/^\d{2}$/',$state))throw new Exception('State Code must be exactly 2 digits.');$tier=is_super_admin()?($_POST['price_tier']??'retail'):'retail';$limit=is_super_admin()?max(0,(float)($_POST['credit_limit']??0)):0;if($name==='')throw new Exception('Customer name required.');if(!in_array($tier,['retail','wholesale','dealer','offer'],true))$tier='retail';if($code==='')$code='CUS-'.date('ymdHis').random_int(10,99);$st=db()->prepare('INSERT INTO customers(customer_code,name,mobile,gstin,address,state_code,price_tier,credit_limit,active) VALUES(?,?,?,?,?,?,?,?,1)');$st->execute([$code,$name,$mobile,$gstin,$address,$state,$tier,$limit]);$id=(int)db()->lastInsertId();audit('CUSTOMER_CREATE','customer',$id);$msg='Customer created.';}
 elseif($action==='receipt'&&is_super_admin()){$cid=(int)$_POST['customer_id'];$amount=(float)$_POST['amount'];$remarks=trim($_POST['remarks']??'');if($amount<=0)throw new Exception('Receipt amount must be positive.');db()->prepare("INSERT INTO customer_ledger(customer_id,txn_type,credit,reference_type,remarks,created_by) VALUES(?,'RECEIPT',?,'RECEIPT',?,?)")->execute([$cid,$amount,$remarks,current_user()['id']]);audit('CUSTOMER_RECEIPT','customer',$cid,['amount'=>$amount]);$msg='Receipt posted.';}
 elseif($action==='toggle'&&is_super_admin()){$cid=(int)$_POST['customer_id'];db()->prepare('UPDATE customers SET active=1-active WHERE id=?')->execute([$cid]);audit('CUSTOMER_TOGGLE','customer',$cid);}
 }catch(Throwable $e){$err=$e->getMessage();}}
$q=trim($_GET['q']??'');$args=[];$sql="SELECT c.*,COALESCE(SUM(cl.debit-cl.credit),0) outstanding FROM customers c LEFT JOIN customer_ledger cl ON cl.customer_id=c.id WHERE 1";if($q!==''){$sql.=' AND (c.name LIKE ? OR c.mobile LIKE ? OR c.customer_code LIKE ?)';$like='%'.$q.'%';$args=[$like,$like,$like];}$sql.=' GROUP BY c.id ORDER BY c.id DESC LIMIT 500';$st=db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();page_header('Customer Master & Credit Ledger');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="get" class="actions no-print"><input name="q" value="<?=e($q)?>" placeholder="Customer / mobile / code"><button class="btn">Search</button></form><br>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="row3"><div><label>Customer Code</label><input name="customer_code" placeholder="Auto if blank"></div><div><label>Customer / Party Name</label><input name="name" required></div><div><label>Mobile</label><input name="mobile"></div></div><br><div class="row3"><div><label>GSTIN</label><input name="gstin"></div><div><label>State Code</label><input name="state_code" maxlength="2"></div><div><?php if(is_super_admin()):?><label>Price Tier</label><select name="price_tier"><option value="retail">Retail</option><option value="wholesale">Wholesale</option><option value="dealer">Dealer</option><option value="offer">Offer</option></select><?php else:?><label>Price Tier</label><input value="Retail · Admin can change special tiers" readonly><?php endif;?></div></div><br><div class="row"><div><?php if(is_super_admin()):?><label>Credit Limit</label><input type="number" min="0" step="0.01" name="credit_limit" value="0"><?php else:?><label>Credit Limit</label><input value="0 · Admin only" readonly><?php endif;?></div><div><label>Address</label><input name="address"></div></div><br><button class="btn">Add Customer</button></form><br>
<table><tr><th>Code</th><th>Customer</th><th>Mobile</th><th>Tier</th><th>Limit</th><th>Outstanding</th><th>Receipt</th><th>Edit</th><?php if(is_super_admin()):?><th>Status</th><?php endif;?></tr><?php foreach($rows as $r):?><tr><td><?=e($r['customer_code'])?></td><td><?=e($r['name'])?><div class="muted"><?=e($r['gstin'])?></div></td><td><?=e($r['mobile'])?></td><td><?=e($r['price_tier'])?></td><td>₹<?=e(number_format($r['credit_limit'],2))?></td><td>₹<?=e(number_format($r['outstanding'],2))?></td><td><?php if(is_super_admin()):?><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="receipt"><input type="hidden" name="customer_id" value="<?=$r['id']?>"><input type="number" min="0.01" step="0.01" name="amount" placeholder="Amount" style="width:110px" required><input name="remarks" placeholder="Ref" style="width:100px"><button class="btn secondary">Post</button></form><?php else:?>Admin only<?php endif;?></td><td><a href="customer_edit.php?id=<?=$r['id']?>">Edit</a></td><?php if(is_super_admin()):?><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="customer_id" value="<?=$r['id']?>"><button class="btn secondary"><?=$r['active']?'Active':'Inactive'?></button></form></td><?php endif;?></tr><?php endforeach;?></table><?php page_footer();
